const { state, labels, assignee, sort, maxResults } = $.input;
const params = {};
params.state = state || 'open';
params.sort = sort || 'created';
params.per_page = String(Math.max(1, Math.min(100, maxResults || 10)));
if (labels) params.labels = labels;
if (assignee) params.assignee = assignee;
return { params };

const resp = $.steps.listIssues.response || [];
const issues = (Array.isArray(resp) ? resp : []).filter(i => !i.pull_request);
const shouldFetchComments = $.input.includeComments && issues.length > 0;
return { issues, count: shouldFetchComments ? issues.length : 0 };

const comments = $.steps.getComments?.response || [];
return {
  issueNumber: $.loop.issue.number,
  comments: (Array.isArray(comments) ? comments : []).map(c => ({
    id: c.id,
    author: c.user?.login || 'unknown',
    body: c.body?.substring(0, 500) || '',
    createdAt: c.created_at
  }))
};

const issues = $.steps.filterIssues.output.issues || [];
const commentIterations = $.steps.fetchComments?.response?.iterations || [];

const commentMap = {};
commentIterations.forEach(iter => {
  const parsed = iter?.parseComments?.output;
  if (parsed) commentMap[parsed.issueNumber] = parsed.comments;
});

const result = issues.map(i => {
  const item = {
    number: i.number,
    title: i.title,
    state: i.state,
    author: i.user?.login || 'unknown',
    assignees: (i.assignees || []).map(a => a.login),
    labels: (i.labels || []).map(l => typeof l === 'string' ? l : l.name),
    createdAt: i.created_at,
    updatedAt: i.updated_at,
    body: (i.body || '').substring(0, 500),
    commentsCount: i.comments || 0,
    url: i.html_url
  };
  if (commentMap[i.number]) item.comments = commentMap[i.number];
  return item;
});

return {
  issues: result,
  totalFound: result.length,
  repo: $.input.owner + '/' + $.input.repo,
  filters: { state: $.input.state || 'open', labels: $.input.labels || 'any', assignee: $.input.assignee || 'any' },
  summary: 'Found ' + result.length + ' issue' + (result.length === 1 ? '' : 's') + ' in ' + $.input.owner + '/' + $.input.repo
};
